const profiles = [{
  profile_id: 'python-fastapi-3.12',
  application_type: 'http-api',
  allowed_repositories: ['labadmin/demo-fastapi'],
  language: 'python',
  runtime: '3.12',
  framework: 'fastapi',
  entrypoint: 'app.main:app',
  source_root: 'app',
  health_path: '/health',
  openapi_path: '/openapi.json',
  test_runner: 'pytest',
  production_dependency_file: 'requirements.txt',
  test_dependency_file: 'requirements-dev.txt',
  required_files: [
    'app/__init__.py', 'app/main.py', 'requirements.txt',
    'requirements-dev.txt', 'README.md', 'docs/USER_GUIDE.md',
    'docs/ADMIN_GUIDE.md', 'docs/TECHNICAL_DESCRIPTION.md'
  ],
  documentation: {
    required: true,
    files: ['README.md', 'docs/USER_GUIDE.md', 'docs/ADMIN_GUIDE.md', 'docs/TECHNICAL_DESCRIPTION.md'],
    test_report_file: 'test-report.md',
    test_report_owner: 'ci'
  },
  context_files: [
    'README.md', 'pyproject.toml', 'requirements.txt', 'requirements-dev.txt',
    'docs/USER_GUIDE.md', 'docs/ADMIN_GUIDE.md', 'docs/TECHNICAL_DESCRIPTION.md'
  ],
  context_roots: ['app', 'tests', 'docs'],
  allowed_empty_basenames: ['__init__.py'],
  capabilities: {
    http: true, cli: false, health: true, openapi: true,
    sast: true, dast: true, runtime_smoke: true,
    api_fuzzing: false, persistent_storage: false
  },
  test_commands: ['python -m pytest -q'],
  security_checks: {
    static: ['semgrep'], dynamic: ['owasp-zap-baseline'], fuzzing: []
  },
  build: {
    strategy: 'platform-template', template_id: 'python-fastapi-3.12',
    context: '.', container_port: 8000
  },
  limits: {
    max_plan_files: 15,
    max_generated_files: 15,
    max_context_files: 30,
    max_file_chars: 20000,
    max_payload_chars: 55000
  }
}];
return {schema_version: '1.0', catalog_version: '2026-08-02.fastapi-v5', profiles};

const selection = {
  supported: <implementationprofileselector.result.supported>,
  needs_human: <implementationprofileselector.result.needs_human>,
  profile_id: String(
    <implementationprofileselector.result.profile_id> ?? ''
  ).trim(),
  language: String(
    <implementationprofileselector.result.language> ?? ''
  ).trim(),
  runtime: String(
    <implementationprofileselector.result.runtime> ?? ''
  ).trim(),
  framework: String(
    <implementationprofileselector.result.framework> ?? ''
  ).trim(),
  entrypoint: String(
    <implementationprofileselector.result.entrypoint> ?? ''
  ).trim(),
  source_root: String(
    <implementationprofileselector.result.source_root> ?? ''
  ).trim(),
  health_path: String(
    <implementationprofileselector.result.health_path> ?? ''
  ).trim(),
  openapi_path: String(
    <implementationprofileselector.result.openapi_path> ?? ''
  ).trim(),
  test_runner: String(
    <implementationprofileselector.result.test_runner> ?? ''
  ).trim(),
  production_dependency_file: String(
    <implementationprofileselector.result.production_dependency_file> ?? ''
  ).trim(),
  test_dependency_file: String(
    <implementationprofileselector.result.test_dependency_file> ?? ''
  ).trim(),
  reason: String(
    <implementationprofileselector.result.reason> ?? ''
  ).trim()
};

const catalogVersion = String(
  <implementationprofilecatalog.result.catalog_version> ?? ''
).trim();

const catalogProfiles = Array.isArray(
  <implementationprofilecatalog.result.profiles>
)
  ? <implementationprofilecatalog.result.profiles>
  : [];

const errors = [];
const targetRepository = `${String(
  <validaterequirementsinput.result.owner> ?? ''
).trim()}/${String(
  <validaterequirementsinput.result.repo> ?? ''
).trim()}`;

if (!selection.reason) {
  errors.push('Implementation Profile Selector не указал reason');
}

// Неподдерживаемый запрос является штатным результатом выбора.
// valid=false направит выполнение в существующую ветку Unsupported Profile.
if (selection.supported !== true) {
  if (selection.needs_human !== true) {
    errors.push(
      'Для неподдерживаемого запроса needs_human должен быть true'
    );
  }

  if (selection.profile_id !== '') {
    errors.push(
      'Для неподдерживаемого запроса profile_id должен быть пустой строкой'
    );
  }

  return {
    valid: false,
    errors: [
      selection.reason || 'Подходящий implementation profile не найден',
      ...errors
    ],
    profile: null,
    selection,
    catalog_version: catalogVersion
  };
}

if (selection.needs_human !== false) {
  errors.push(
    'Для поддерживаемого запроса needs_human должен быть false'
  );
}

const canonical = catalogProfiles.find(
  (item) =>
    item &&
    typeof item === 'object' &&
    String(item.profile_id ?? '') === selection.profile_id
);

if (!canonical) {
  errors.push(
    `profile_id отсутствует в доверенном каталоге: ${selection.profile_id}`
  );
}

const selectorFields = [
  'profile_id',
  'language',
  'runtime',
  'framework',
  'entrypoint',
  'source_root',
  'health_path',
  'openapi_path',
  'test_runner',
  'production_dependency_file',
  'test_dependency_file'
];

if (canonical) {
  const profileRepositories = Array.isArray(
    canonical.allowed_repositories
  )
    ? canonical.allowed_repositories.map((item) => String(item ?? ''))
    : [];

  if (!profileRepositories.includes(targetRepository)) {
    errors.push(
      `Профиль ${canonical.profile_id} не разрешён для ` +
      `репозитория ${targetRepository}`
    );
  }

  for (const field of selectorFields) {
    const expected = String(canonical[field] ?? '').trim();
    const actual = String(selection[field] ?? '').trim();

    if (actual !== expected) {
      errors.push(
        `${field} не совпадает с доверенным каталогом: ` +
        `ожидалось ${JSON.stringify(expected)}, ` +
        `получено ${JSON.stringify(actual)}`
      );
    }
  }
}

return {
  valid: errors.length === 0,
  errors,
  // Дальше передаётся не объект, составленный моделью,
  // а каноническая запись из доверенного каталога.
  profile: canonical
    ? {
        ...canonical,
        catalog_version: catalogVersion,
        selection_reason: selection.reason
      }
    : null,
  selection,
  catalog_version: catalogVersion
};

const decision = String(<architectureapproval.decision> ?? '').trim().toLowerCase();
const comments = String(<architectureapproval.comments> ?? '').trim();
const reviewerPassed = Boolean(<validatearchitecturereview.result.review.passed>);
const allowed = ['approve', 'revise', 'reject'];
const commentsRequired = decision === 'revise' || decision === 'reject';
const gateBlocked = decision === 'approve' && !reviewerPassed;
const valid = allowed.includes(decision) && !gateBlocked && (!commentsRequired || comments.length > 0);
return {
  decision, comments, valid,
  error: !allowed.includes(decision)
    ? 'Допустимы approve, revise или reject.'
    : gateBlocked
      ? 'Approve запрещён: Architecture Reviewer не прошёл quality gate. Выберите revise или reject.'
      : commentsRequired && !comments
        ? 'Для revise или reject требуется комментарий.'
        : ''
};

return {
  status: 'unsupported_implementation_profile',
  run_id: String(
    <validaterequirementsinput.result.run_id> ?? ''
  ),
  errors: Array.isArray(
    <validateimplementationprofile.result.errors>
  )
    ? <validateimplementationprofile.result.errors>
    : [],
  profile:
    <validateimplementationprofile.result.profile>,
  manual_intervention_required: true
};

const base = <resolvearchitecturecontext.result>;
const runId = String(base.run_id);
const revision = Number(base.architecture_revision);
const fileName = `architecture-r${revision}.json`;
const artifactRef = {owner: String(<start.artifact_owner>), package: String(<start.artifact_package>), version: String(<start.artifact_version>), file: fileName};
const artifact = {
  schema_version: '2.0',
  workflow_id: '02-architecture',
  workflow_version: '5.0',
  status: 'approved',
  artifact_id: `${runId}:architecture:${revision}`,
  run_id: runId,
  architecture_revision: revision,
  owner: base.owner,
  repo: base.repo,
  base_branch: base.base_branch,
  requirements_artifact: base.artifact,
  requirements_artifact_ref: {owner: String(<start.artifact_owner>), package: String(<start.artifact_package>), version: String(<start.artifact_version>), file: String(<start.requirements_file>)},
  implementation_profile: <validateimplementationprofile.result.profile>,
  architecture: <validatearchitectureoutput.result.document>,
  repository_plan: <validaterepositoryplan.result.plan>,
  review: {
    ...<validatearchitecturereview.result.review>,
    traceability_warnings: <validaterepositoryplan.result.warnings>,
    plan_statistics: <validaterepositoryplan.result.statistics>
  },
  approval: {
    decision: <normalizearchitecturedecision.result.decision>,
    comments: <normalizearchitecturedecision.result.comments>,
    submitted_at: <architectureapproval.submittedAt>
  },
  artifact_ref: artifactRef,
  next_workflow: '03-implementation'
};
return {...artifact, artifact_json: JSON.stringify(artifact), artifact_file: fileName};

return {
  status: 'rejected',
  run_id: String(<validaterequirementsinput.result.run_id> ?? ''),
  architecture_revision: Number(<validaterequirementsinput.result.architecture_revision>),
  comments: String(<normalizearchitecturedecision.result.comments> ?? '')
};

return {
  status: 'invalid_requirements_input',
  run_id: String(<validaterequirementsinput.result.run_id> ?? ''),
  errors: Array.isArray(<validaterequirementsinput.result.errors>)
    ? <validaterequirementsinput.result.errors>
    : []
};

const files = <repositoryplanner.files>;
const profile = <validateimplementationprofile.result.profile>;
const errors = [];
const warnings = [];

const forbiddenPrefixes = [
  '.git/',
  '.gitea/',
  '.github/',
  'ci/',
  'k8s/',
  'policies/',
  'secrets/',
  'vendor/',
  'node_modules/',
  'dist/',
  'build/',
  'artifacts/'
];

const forbiddenBasenames = new Set([
  '.env',
  '.env.local',
  'secrets.yaml',
  'secrets.yml',
  'id_rsa',
  'id_ed25519'
]);

const forbiddenSecretExtension = /\.(pem|key|p12|pfx)$/i;
const pathPattern =
  /^(?!\/)(?!.*\.\.)(?!.*\\)(?!.*\/\/)[A-Za-z0-9._/-]+$/;

const maxPlanFiles = Number(
  profile?.limits?.max_plan_files ?? 50
);

if (!Array.isArray(files)) {
  errors.push('files должен быть массивом');
}

if (
  Array.isArray(files) &&
  (files.length < 1 || files.length > maxPlanFiles)
) {
  errors.push(
    `files должен содержать 1..${maxPlanFiles} элементов`
  );
}

const seen = new Set();
const normalizedFiles = [];

for (const file of Array.isArray(files) ? files : []) {
  const path = String(file?.path ?? '').trim();
  const lower = path.toLowerCase();
  const basename = lower.split('/').pop() ?? '';
  const purpose = String(file?.purpose ?? '').trim();

  if (!path) {
    errors.push('Обнаружен файл с пустым path');
  }

  if (path && !pathPattern.test(path)) {
    errors.push(`Недопустимый path: ${path}`);
  }

  if (
    forbiddenBasenames.has(basename) ||
    forbiddenSecretExtension.test(lower) ||
    forbiddenPrefixes.some((prefix) => lower.startsWith(prefix))
  ) {
    errors.push(`Запрещённый path: ${path}`);
  }

  if (seen.has(lower)) {
    errors.push(`Дублирующийся path: ${path}`);
  }

  seen.add(lower);

  if (!purpose) {
    errors.push(`Нет purpose: ${path || '<empty path>'}`);
  }

  if (!Array.isArray(file?.requirement_ids)) {
    errors.push(
      `requirement_ids должен быть массивом: ${path || '<empty path>'}`
    );
  }

  const requirementIds = Array.isArray(file?.requirement_ids)
    ? [
        ...new Set(
          file.requirement_ids
            .map((id) => String(id ?? '').trim())
            .filter(Boolean)
        )
      ]
    : [];

  if (requirementIds.length === 0) {
    warnings.push(
      `Нет прямой трассировки требований: ${path || '<empty path>'}`
    );
  }

  normalizedFiles.push({
    path,
    encoded_path: path
      .split('/')
      .map(encodeURIComponent)
      .join('/'),
    purpose,
    requirement_ids: requirementIds
  });
}

// Универсальный валидатор не знает про FastAPI напрямую.
// Он проверяет required_files выбранного доверенного профиля.
const requiredFiles = Array.isArray(profile?.required_files)
  ? profile.required_files
      .map((path) => String(path ?? '').trim())
      .filter(Boolean)
  : [];

for (const requiredPath of requiredFiles) {
  if (!seen.has(requiredPath.toLowerCase())) {
    errors.push(
      `В repository plan отсутствует обязательный файл профиля: ${requiredPath}`
    );
  }
}

const normalizedDirectories = [
  ...new Set(
    normalizedFiles.flatMap((file) => {
      const parts = file.path.split('/');
      const directories = [];

      for (let i = 1; i < parts.length; i++) {
        directories.push(parts.slice(0, i).join('/'));
      }

      return directories;
    })
  )
].sort();

const developerNotes = Array.isArray(
  <repositoryplanner.developer_notes>
)
  ? <repositoryplanner.developer_notes>
      .map((note) => String(note ?? '').trim())
      .filter(Boolean)
  : [];

const summary = String(
  <repositoryplanner.summary> ?? ''
).trim();

if (!summary) {
  errors.push('Repository Planner не указал summary');
}

const statistics = {
  file_count: normalizedFiles.length,
  directory_count: normalizedDirectories.length,
  files_without_requirement_ids: normalizedFiles.filter(
    (file) => file.requirement_ids.length === 0
  ).length,
  required_profile_files: requiredFiles.length
};

return {
  valid: errors.length === 0,
  errors,
  warnings,
  statistics,
  plan: {
    summary,
    directories: normalizedDirectories,
    files: normalizedFiles,
    developer_notes: developerNotes,
    traceability_warnings: warnings,
    statistics
  }
};

return {
  status: 'invalid_repository_plan',
  run_id: String(<validaterequirementsinput.result.run_id> ?? ''),
  errors: Array.isArray(<validaterepositoryplan.result.errors>)
    ? <validaterepositoryplan.result.errors>
    : []
};

const base = <resolvearchitecturecontext.result>;
const revision = Number(base.architecture_revision);
if (!Number.isInteger(revision) || revision >= 10) throw new Error('Достигнут лимит редакций архитектуры.');
const fileName = `architecture-r${revision}.json`;
const artifactRef = {owner: String(<start.artifact_owner>), package: String(<start.artifact_package>), version: String(<start.artifact_version>), file: fileName};
const artifact = {
  schema_version: '2.0',
  workflow_id: '02-architecture',
  workflow_version: '5.0',
  status: 'revision_requested',
  run_id: base.run_id,
  architecture_revision: revision,
  owner: base.owner,
  repo: base.repo,
  base_branch: base.base_branch,
  requirements_artifact: base.artifact,
  implementation_profile: <validateimplementationprofile.result.profile>,
  architecture: <validatearchitectureoutput.result.document>,
  repository_plan: <validaterepositoryplan.result.plan>,
  review: <validatearchitecturereview.result.review>,
  approval: {
    decision: <normalizearchitecturedecision.result.decision>,
    comments: <normalizearchitecturedecision.result.comments>,
    submitted_at: <architectureapproval.submittedAt>
  },
  artifact_ref: artifactRef
};
return {...artifact, next_architecture_revision: revision + 1, artifact_json: JSON.stringify(artifact), artifact_file: fileName};

const errors = [];
const raw = <getrequirementsartifact.data>;
let artifact = null;
if (Number(<getrequirementsartifact.status>) !== 200 || !raw) {
  errors.push('Артефакт требований не получен из Gitea');
} else {
  artifact = raw;
  for (let attempt = 0; attempt < 2 && typeof artifact === 'string'; attempt += 1) {
    try {
      artifact = JSON.parse(artifact);
    } catch (_) {
      errors.push('Артефакт требований не является валидным JSON');
      artifact = null;
      break;
    }
  }
  if (artifact?.data && typeof artifact.data === 'object' && !Array.isArray(artifact.data)) {
    artifact = artifact.data;
  }
  if (!artifact || typeof artifact !== 'object' || Array.isArray(artifact)) {
    errors.push('Артефакт требований не является JSON-объектом');
    artifact = null;
  }
}

const owner = String(<start.target_owner> ?? '').trim();
const repo = String(<start.target_repo> ?? '').trim();
const baseBranch = String(<start.base_branch> ?? '').trim();
const revision = Number(<start.architecture_revision> ?? 1);
const revisionComments = String(<start.revision_comments> ?? '').trim();
const allowedRepositories = new Set(['labadmin/demo-fastapi']);

if (!allowedRepositories.has(`${owner}/${repo}`)) errors.push('repository отсутствует в allowlist');
if (baseBranch !== 'main') errors.push('разрешена только base_branch=main');
if (!Number.isInteger(revision) || revision < 1 || revision > 10) errors.push('architecture_revision должен быть 1..10');
if (revision > 1 && !revisionComments) errors.push('для revise нужны revision_comments');

if (artifact) {
  if (artifact.schema_version !== '3.0') errors.push('неподдерживаемая schema_version требований');
  if (artifact.workflow_id !== '01-requirements') errors.push('неверный workflow_id требований');
  if (artifact.status !== 'approved') errors.push('требования не утверждены');
  if (artifact.quality_gate?.passed !== true) errors.push('quality gate требований не пройден');
  if (artifact.approval?.decision !== 'approve') errors.push('нет человеческого approve требований');
  if (!/^run-\d{8}-\d{6}-[a-z0-9]{6}$/.test(String(artifact.run_id ?? ''))) errors.push('некорректный run_id');
  if (String(artifact.specification ?? '').trim().length < 100) errors.push('specification отсутствует или слишком короткая');
}

return {
  valid: errors.length === 0,
  errors,
  artifact,
  run_id: artifact?.run_id ?? '',
  owner,
  repo,
  base_branch: baseBranch,
  architecture_revision: revision,
  architecture_revision_minus_one: revision - 1,
  mode: revision > 1 ? 'revise' : 'create',
  previous_architecture: '',
  previous_repository_plan: null,
  revision_comments: revisionComments
};

const base = <validaterequirementsinput.result>;
let previousArchitecture = '';
let previousPlan = null;
if (Number(base.architecture_revision) > 1) {
  const raw = <getpreviousarchitectureartifact.data>;
  let artifact = raw;
  for (let attempt = 0; attempt < 2 && typeof artifact === 'string'; attempt += 1) {
    try {
      artifact = JSON.parse(artifact);
    } catch (_) {
      throw new Error('Предыдущий артефакт архитектуры не является валидным JSON.');
    }
  }
  if (artifact?.data && typeof artifact.data === 'object' && !Array.isArray(artifact.data)) {
    artifact = artifact.data;
  }
  if (Number(<getpreviousarchitectureartifact.status>) !== 200 || !artifact || typeof artifact !== 'object') throw new Error('Предыдущий артефакт архитектуры не получен.');
  if (String(artifact.run_id ?? '') !== String(base.run_id)) throw new Error('run_id предыдущей архитектуры не совпадает.');
  if (Number(artifact.architecture_revision) !== Number(base.architecture_revision) - 1) throw new Error('Номер предыдущей архитектуры не совпадает.');
  previousArchitecture = String(artifact.architecture ?? '').trim();
  previousPlan = artifact.repository_plan ?? null;
  if (previousArchitecture.length < 100 || !Array.isArray(previousPlan?.files)) throw new Error('Предыдущий артефакт архитектуры неполон.');
}
return {...base, mode: Number(base.architecture_revision) > 1 ? 'revise' : 'create', previous_architecture: previousArchitecture, previous_repository_plan: previousPlan};

const document = String(<solutionarchitect.content> ?? '').trim();
const errors = [];
if (document.length < 500) errors.push('Архитектура слишком короткая');
if (document.length > 22000) errors.push('Архитектура превышает 22000 символов');
if (!document.endsWith('<!-- COMPLETE:ARCHITECTURE -->')) errors.push('Нет завершающего маркера; вероятна обрезка');
if (/[\u3400-\u9fff]/u.test(document)) errors.push('Обнаружены китайские иероглифы');
if (/<\/?think>/iu.test(document)) errors.push('В ответ попало внутреннее рассуждение');
return {valid: errors.length === 0, errors, document, length: document.length};

const review = {
  passed: <architecturereviewer.passed>,
  missing_requirements: <architecturereviewer.missing_requirements>,
  security_gaps: <architecturereviewer.security_gaps>,
  plan_violations: <architecturereviewer.plan_violations>,
  contradictions: <architecturereviewer.contradictions>,
  summary: <architecturereviewer.summary>
};
const errors = [];
if (typeof review.passed !== 'boolean') errors.push('review.passed не boolean');
for (const key of ['missing_requirements','security_gaps','plan_violations','contradictions']) {
  if (!Array.isArray(review[key])) errors.push(`review.${key} не массив`);
  else if (review[key].some((item) => typeof item !== 'string' || item.length > 800)) errors.push(`review.${key} содержит некорректный элемент`);
}
if (typeof review.summary !== 'string' || review.summary.trim().length < 10 || review.summary.length > 2000) errors.push('review.summary отсутствует или имеет неверный размер');
return {valid: errors.length === 0, errors, review};

const status = Number(<publisharchitectureartifact.status>);
if (![200, 201, 204, 409].includes(status)) throw new Error(`Gitea не сохранила артефакт архитектуры: HTTP ${status}`);
return {valid: true, status};

const status = Number(<triggerworkflow03.status>);
if (![200, 202].includes(status)) throw new Error(`Workflow 03 не поставлен в очередь: HTTP ${status}`);
return {valid: true, status};

const artifact = <buildarchitectureresult.result>;
return {
  schema_version: artifact.schema_version,
  workflow_id: artifact.workflow_id,
  workflow_version: artifact.workflow_version,
  status: 'approved_and_forwarded',
  run_id: artifact.run_id,
  architecture_revision: artifact.architecture_revision,
  artifact_id: artifact.artifact_id,
  artifact_ref: artifact.artifact_ref,
  next_workflow: artifact.next_workflow,
  next_execution_http_status: Number(<triggerworkflow03.status>)
};

const artifact = <buildarchitecturerevision.result>;
return {
  status: 'revision_queued',
  run_id: artifact.run_id,
  current_revision: artifact.architecture_revision,
  next_architecture_revision: artifact.next_architecture_revision,
  artifact_ref: artifact.artifact_ref,
  revision_comments: artifact.approval.comments,
  next_execution_http_status: Number(<triggerworkflow02revision.status>)
};

const status = Number(<publisharchitecturerevision.status>);
if (![200, 201, 204, 409].includes(status)) throw new Error(`Gitea не сохранила редакцию архитектуры: HTTP ${status}`);
return {valid: true, status};

const status = Number(<triggerworkflow02revision.status>);
if (![200, 202].includes(status)) throw new Error(`Новая редакция Workflow 02 не поставлена в очередь: HTTP ${status}`);
return {valid: true, status};
